.ds-primary { display: flex; min-height: 48px; align-items: center; justify-content: space-between; gap: 24px; margin-top: 24px; border-radius: 8px; padding: 12px 20px; background: #285342; color: white; font-weight: 600; text-decoration: none; transition: background-color 150ms ease; }
.ds-primary:hover { background: #183b2e; }
.ds-primary { margin-top: 20px; }
.ds-primary { font-family: Manrope, -apple-system, sans-serif; box-sizing: border-box; } .ds-primary:focus-visible { outline: 3px solid #285342; outline-offset: 3px; } @media(prefers-reduced-motion:reduce) { .ds-primary {transition:none;} }
